export const CLASSES={sword:{name:'Мечник',damage:9.75,cooldown:.65,incoming:.8,regen:1,stamina:1},bow:{name:'Лучник',damage:6.5,cooldown:.9,incoming:1,regen:1,stamina:2},mage:{name:'Маг',damage:13,cooldown:.9,incoming:1.1,regen:.5,stamina:1}};
export function createProgress(){return {stage:'safe',rejected:false,classId:null,xp:0,level:1,arrows:0,rewards:[],wolfDead:false,pendingLevels:0}}
export function reward(p,id,kind,amount){if(p.rewards.includes(id))return false;p.rewards.push(id);p.xp+=amount??({quest:40,monster:10,mob:5})[kind];while(p.xp>=250){p.xp-=250;p.level++;p.pendingLevels=(p.pendingLevels||0)+1}return true}
export function chooseClass(p,id){if(p.classId||p.stage!=='smith'||!CLASSES[id])return false;p.classId=id;p.arrows=id==='bow'?50:0;p.stage='armed';return true}
export function objective(p){return {safe:'Найдите безопасное место',offer:'',smith:'Поговорите с кузнецом',armed:'Подойти к Альфреду',wolf:'Победить волка, который бродит у деревни',report:'Вернуться к Альфреду',forest:'Идти в глубь леса',carcasses:'Соберите 3 туши кроликов',delivery:'Вернитесь в деревню',complete:'Поговорите с Мэри',mary_offer:'Поговорите с Мэри',water:'Наберите воду из озера Лонслек',ambush:'Победите волков у озера',water_return:'Вернитесь к Мэри',mary_done:'',hunter_travel:'Отправляйтесь в глубины Темнолесья',hunter_search:'Найдите обезумевшего охотника',hunter_talk:'Поговорите с охотником',hunter_return:'Вернитесь к Альфреду',witch_offer:'',witch:'Победите Ведьму',witch_return:'Вернитесь к Альфреду',witch_done:''}[p.stage]}
export function admit(p){if(p.stage!=='safe')return false;reward(p,'safe','quest');p.stage='offer';return true}
export function kill(p,id,kind){reward(p,id,kind);if(id==='wolf'){p.wolfDead=true;if(p.stage==='wolf')p.stage='report'}}
